// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Log in with email and password
	// (POST /auth/login)
	AuthLogin(w http.ResponseWriter, r *http.Request)
	// Revoke current session
	// (POST /auth/logout)
	AuthLogout(w http.ResponseWriter, r *http.Request)
	// Rotate refresh token
	// (POST /auth/refresh)
	AuthRefresh(w http.ResponseWriter, r *http.Request)
	// Register a new user
	// (POST /auth/register)
	AuthRegister(w http.ResponseWriter, r *http.Request)
	// List own devices
	// (GET /devices)
	ListDevices(w http.ResponseWriter, r *http.Request)
	// Register a device (idempotent by hardware_id)
	// (POST /devices)
	CreateDevice(w http.ResponseWriter, r *http.Request)
	// Delete device and revoke ingest tokens
	// (DELETE /devices/{id})
	DeleteDevice(w http.ResponseWriter, r *http.Request, id DeviceId)
	// Get own device
	// (GET /devices/{id})
	GetDevice(w http.ResponseWriter, r *http.Request, id DeviceId)
	// Rename device
	// (PATCH /devices/{id})
	PatchDevice(w http.ResponseWriter, r *http.Request, id DeviceId)
	// List ingest tokens (metadata only)
	// (GET /devices/{id}/ingest-tokens)
	ListIngestTokens(w http.ResponseWriter, r *http.Request, id DeviceId)
	// Create ingest token (plain token returned once)
	// (POST /devices/{id}/ingest-tokens)
	CreateIngestToken(w http.ResponseWriter, r *http.Request, id DeviceId)
	// Revoke ingest token
	// (DELETE /devices/{id}/ingest-tokens/{token_id})
	RevokeIngestToken(w http.ResponseWriter, r *http.Request, id DeviceId, tokenId TokenId)
	// Groups the user belongs to
	// (GET /groups)
	ListGroups(w http.ResponseWriter, r *http.Request)
	// Create a group
	// (POST /groups)
	CreateGroup(w http.ResponseWriter, r *http.Request)
	// Join group by invite code
	// (POST /groups/join)
	JoinGroup(w http.ResponseWriter, r *http.Request)
	// Delete group (owner only)
	// (DELETE /groups/{id})
	DeleteGroup(w http.ResponseWriter, r *http.Request, id GroupId)
	// Group detail with members
	// (GET /groups/{id})
	GetGroup(w http.ResponseWriter, r *http.Request, id GroupId)
	// Rename group (admin+)
	// (PATCH /groups/{id})
	PatchGroup(w http.ResponseWriter, r *http.Request, id GroupId)
	// Rotate invite code (admin+)
	// (POST /groups/{id}/invite/rotate)
	RotateGroupInvite(w http.ResponseWriter, r *http.Request, id GroupId)
	// Leave group
	// (POST /groups/{id}/leave)
	LeaveGroup(w http.ResponseWriter, r *http.Request, id GroupId)
	// Server-Sent Events live presence stream
	// (GET /groups/{id}/live)
	GetGroupLive(w http.ResponseWriter, r *http.Request, id GroupId)
	// Remove member (admin+, rules apply)
	// (DELETE /groups/{id}/members/{user_id})
	RemoveGroupMember(w http.ResponseWriter, r *http.Request, id GroupId, userId UserId)
	// Change role or transfer ownership (owner)
	// (PATCH /groups/{id}/members/{user_id})
	PatchGroupMember(w http.ResponseWriter, r *http.Request, id GroupId, userId UserId)
	// Member-visible aggregated data
	// (GET /groups/{id}/overview)
	GetGroupOverview(w http.ResponseWriter, r *http.Request, id GroupId, params GetGroupOverviewParams)
	// Privacy defaults, overrides and effective flags in this group
	// (GET /groups/{id}/privacy)
	GetGroupPrivacy(w http.ResponseWriter, r *http.Request, id GroupId)
	// Set per-group privacy overrides
	// (PUT /groups/{id}/privacy)
	PutGroupPrivacy(w http.ResponseWriter, r *http.Request, id GroupId)
	// Batch ingest from device
	// (POST /ingest)
	IngestEvents(w http.ResponseWriter, r *http.Request)
	// Delete account and all data
	// (DELETE /me)
	DeleteMe(w http.ResponseWriter, r *http.Request)
	// Current user profile
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// Update profile
	// (PATCH /me)
	PatchMe(w http.ResponseWriter, r *http.Request)
	// GDPR export of all own data
	// (GET /me/export)
	ExportMe(w http.ResponseWriter, r *http.Request)
	// Change password and revoke other sessions
	// (POST /me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// User privacy defaults
	// (GET /me/privacy-defaults)
	GetPrivacyDefaults(w http.ResponseWriter, r *http.Request)
	// Replace privacy defaults
	// (PUT /me/privacy-defaults)
	PutPrivacyDefaults(w http.ResponseWriter, r *http.Request)
	// List puffs with filters
	// (GET /puffs)
	ListPuffs(w http.ResponseWriter, r *http.Request, params ListPuffsParams)
	// Device statistics
	// (GET /stats/devices/{id})
	GetDeviceStats(w http.ResponseWriter, r *http.Request, id DeviceId, params GetDeviceStatsParams)
	// Usage statistics over time
	// (GET /stats/usage)
	GetUsageStats(w http.ResponseWriter, r *http.Request, params GetUsageStatsParams)
}

