// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("POST "+options.BaseURL+"/auth/login", wrapper.AuthLogin)
	m.HandleFunc("POST "+options.BaseURL+"/auth/logout", wrapper.AuthLogout)
	m.HandleFunc("POST "+options.BaseURL+"/auth/refresh", wrapper.AuthRefresh)
	m.HandleFunc("POST "+options.BaseURL+"/auth/register", wrapper.AuthRegister)
	m.HandleFunc("GET "+options.BaseURL+"/devices", wrapper.ListDevices)
	m.HandleFunc("POST "+options.BaseURL+"/devices", wrapper.CreateDevice)
	m.HandleFunc("DELETE "+options.BaseURL+"/devices/{id}", wrapper.DeleteDevice)
	m.HandleFunc("GET "+options.BaseURL+"/devices/{id}", wrapper.GetDevice)
	m.HandleFunc("PATCH "+options.BaseURL+"/devices/{id}", wrapper.PatchDevice)
	m.HandleFunc("GET "+options.BaseURL+"/devices/{id}/ingest-tokens", wrapper.ListIngestTokens)
	m.HandleFunc("POST "+options.BaseURL+"/devices/{id}/ingest-tokens", wrapper.CreateIngestToken)
	m.HandleFunc("DELETE "+options.BaseURL+"/devices/{id}/ingest-tokens/{token_id}", wrapper.RevokeIngestToken)
	m.HandleFunc("GET "+options.BaseURL+"/groups", wrapper.ListGroups)
	m.HandleFunc("POST "+options.BaseURL+"/groups", wrapper.CreateGroup)
	m.HandleFunc("POST "+options.BaseURL+"/groups/join", wrapper.JoinGroup)
	m.HandleFunc("DELETE "+options.BaseURL+"/groups/{id}", wrapper.DeleteGroup)
	m.HandleFunc("GET "+options.BaseURL+"/groups/{id}", wrapper.GetGroup)
	m.HandleFunc("PATCH "+options.BaseURL+"/groups/{id}", wrapper.PatchGroup)
	m.HandleFunc("POST "+options.BaseURL+"/groups/{id}/invite/rotate", wrapper.RotateGroupInvite)
	m.HandleFunc("POST "+options.BaseURL+"/groups/{id}/leave", wrapper.LeaveGroup)
	m.HandleFunc("GET "+options.BaseURL+"/groups/{id}/live", wrapper.GetGroupLive)
	m.HandleFunc("DELETE "+options.BaseURL+"/groups/{id}/members/{user_id}", wrapper.RemoveGroupMember)
	m.HandleFunc("PATCH "+options.BaseURL+"/groups/{id}/members/{user_id}", wrapper.PatchGroupMember)
	m.HandleFunc("GET "+options.BaseURL+"/groups/{id}/overview", wrapper.GetGroupOverview)
	m.HandleFunc("GET "+options.BaseURL+"/groups/{id}/privacy", wrapper.GetGroupPrivacy)
	m.HandleFunc("PUT "+options.BaseURL+"/groups/{id}/privacy", wrapper.PutGroupPrivacy)
	m.HandleFunc("POST "+options.BaseURL+"/ingest", wrapper.IngestEvents)
	m.HandleFunc("DELETE "+options.BaseURL+"/me", wrapper.DeleteMe)
	m.HandleFunc("GET "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc("PATCH "+options.BaseURL+"/me", wrapper.PatchMe)
	m.HandleFunc("GET "+options.BaseURL+"/me/export", wrapper.ExportMe)
	m.HandleFunc("POST "+options.BaseURL+"/me/password", wrapper.ChangePassword)
	m.HandleFunc("GET "+options.BaseURL+"/me/privacy-defaults", wrapper.GetPrivacyDefaults)
	m.HandleFunc("PUT "+options.BaseURL+"/me/privacy-defaults", wrapper.PutPrivacyDefaults)
	m.HandleFunc("GET "+options.BaseURL+"/puffs", wrapper.ListPuffs)
	m.HandleFunc("GET "+options.BaseURL+"/stats/devices/{id}", wrapper.GetDeviceStats)
	m.HandleFunc("GET "+options.BaseURL+"/stats/usage", wrapper.GetUsageStats)

	return m
}

