// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Log in with email and password
	// (POST /auth/login)
	AuthLogin(ctx context.Context, request AuthLoginRequestObject) (AuthLoginResponseObject, error)
	// Revoke current session
	// (POST /auth/logout)
	AuthLogout(ctx context.Context, request AuthLogoutRequestObject) (AuthLogoutResponseObject, error)
	// Rotate refresh token
	// (POST /auth/refresh)
	AuthRefresh(ctx context.Context, request AuthRefreshRequestObject) (AuthRefreshResponseObject, error)
	// Register a new user
	// (POST /auth/register)
	AuthRegister(ctx context.Context, request AuthRegisterRequestObject) (AuthRegisterResponseObject, error)
	// List own devices
	// (GET /devices)
	ListDevices(ctx context.Context, request ListDevicesRequestObject) (ListDevicesResponseObject, error)
	// Register a device (idempotent by hardware_id)
	// (POST /devices)
	CreateDevice(ctx context.Context, request CreateDeviceRequestObject) (CreateDeviceResponseObject, error)
	// Delete device and revoke ingest tokens
	// (DELETE /devices/{id})
	DeleteDevice(ctx context.Context, request DeleteDeviceRequestObject) (DeleteDeviceResponseObject, error)
	// Get own device
	// (GET /devices/{id})
	GetDevice(ctx context.Context, request GetDeviceRequestObject) (GetDeviceResponseObject, error)
	// Rename device
	// (PATCH /devices/{id})
	PatchDevice(ctx context.Context, request PatchDeviceRequestObject) (PatchDeviceResponseObject, error)
	// List ingest tokens (metadata only)
	// (GET /devices/{id}/ingest-tokens)
	ListIngestTokens(ctx context.Context, request ListIngestTokensRequestObject) (ListIngestTokensResponseObject, error)
	// Create ingest token (plain token returned once)
	// (POST /devices/{id}/ingest-tokens)
	CreateIngestToken(ctx context.Context, request CreateIngestTokenRequestObject) (CreateIngestTokenResponseObject, error)
	// Revoke ingest token
	// (DELETE /devices/{id}/ingest-tokens/{token_id})
	RevokeIngestToken(ctx context.Context, request RevokeIngestTokenRequestObject) (RevokeIngestTokenResponseObject, error)
	// Groups the user belongs to
	// (GET /groups)
	ListGroups(ctx context.Context, request ListGroupsRequestObject) (ListGroupsResponseObject, error)
	// Create a group
	// (POST /groups)
	CreateGroup(ctx context.Context, request CreateGroupRequestObject) (CreateGroupResponseObject, error)
	// Join group by invite code
	// (POST /groups/join)
	JoinGroup(ctx context.Context, request JoinGroupRequestObject) (JoinGroupResponseObject, error)
	// Delete group (owner only)
	// (DELETE /groups/{id})
	DeleteGroup(ctx context.Context, request DeleteGroupRequestObject) (DeleteGroupResponseObject, error)
	// Group detail with members
	// (GET /groups/{id})
	GetGroup(ctx context.Context, request GetGroupRequestObject) (GetGroupResponseObject, error)
	// Rename group (admin+)
	// (PATCH /groups/{id})
	PatchGroup(ctx context.Context, request PatchGroupRequestObject) (PatchGroupResponseObject, error)
	// Rotate invite code (admin+)
	// (POST /groups/{id}/invite/rotate)
	RotateGroupInvite(ctx context.Context, request RotateGroupInviteRequestObject) (RotateGroupInviteResponseObject, error)
	// Leave group
	// (POST /groups/{id}/leave)
	LeaveGroup(ctx context.Context, request LeaveGroupRequestObject) (LeaveGroupResponseObject, error)
	// Server-Sent Events live presence stream
	// (GET /groups/{id}/live)
	GetGroupLive(ctx context.Context, request GetGroupLiveRequestObject) (GetGroupLiveResponseObject, error)
	// Remove member (admin+, rules apply)
	// (DELETE /groups/{id}/members/{user_id})
	RemoveGroupMember(ctx context.Context, request RemoveGroupMemberRequestObject) (RemoveGroupMemberResponseObject, error)
	// Change role or transfer ownership (owner)
	// (PATCH /groups/{id}/members/{user_id})
	PatchGroupMember(ctx context.Context, request PatchGroupMemberRequestObject) (PatchGroupMemberResponseObject, error)
	// Member-visible aggregated data
	// (GET /groups/{id}/overview)
	GetGroupOverview(ctx context.Context, request GetGroupOverviewRequestObject) (GetGroupOverviewResponseObject, error)
	// Privacy defaults, overrides and effective flags in this group
	// (GET /groups/{id}/privacy)
	GetGroupPrivacy(ctx context.Context, request GetGroupPrivacyRequestObject) (GetGroupPrivacyResponseObject, error)
	// Set per-group privacy overrides
	// (PUT /groups/{id}/privacy)
	PutGroupPrivacy(ctx context.Context, request PutGroupPrivacyRequestObject) (PutGroupPrivacyResponseObject, error)
	// Batch ingest from device
	// (POST /ingest)
	IngestEvents(ctx context.Context, request IngestEventsRequestObject) (IngestEventsResponseObject, error)
	// Delete account and all data
	// (DELETE /me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// Current user profile
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Update profile
	// (PATCH /me)
	PatchMe(ctx context.Context, request PatchMeRequestObject) (PatchMeResponseObject, error)
	// GDPR export of all own data
	// (GET /me/export)
	ExportMe(ctx context.Context, request ExportMeRequestObject) (ExportMeResponseObject, error)
	// Change password and revoke other sessions
	// (POST /me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// User privacy defaults
	// (GET /me/privacy-defaults)
	GetPrivacyDefaults(ctx context.Context, request GetPrivacyDefaultsRequestObject) (GetPrivacyDefaultsResponseObject, error)
	// Replace privacy defaults
	// (PUT /me/privacy-defaults)
	PutPrivacyDefaults(ctx context.Context, request PutPrivacyDefaultsRequestObject) (PutPrivacyDefaultsResponseObject, error)
	// List puffs with filters
	// (GET /puffs)
	ListPuffs(ctx context.Context, request ListPuffsRequestObject) (ListPuffsResponseObject, error)
	// Device statistics
	// (GET /stats/devices/{id})
	GetDeviceStats(ctx context.Context, request GetDeviceStatsRequestObject) (GetDeviceStatsResponseObject, error)
	// Usage statistics over time
	// (GET /stats/usage)
	GetUsageStats(ctx context.Context, request GetUsageStatsRequestObject) (GetUsageStatsResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// AuthLogin operation middleware
func (sh *strictHandler) AuthLogin(w http.ResponseWriter, r *http.Request) {
	var request AuthLoginRequestObject

	var body AuthLoginJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.AuthLogin(ctx, request.(AuthLoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "AuthLogin")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(AuthLoginResponseObject); ok {
		if err := validResponse.VisitAuthLoginResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

